local _, WFJ = ...
WFJ.Data.add("quest", {
  [9024] = { nil, nil, nil, "Posso aiutarti in qualcosa?", nil, nil, nil, nil, 0xdf112bb5, nil, "mmm.m" },
  [9051] = { "Prova tossica", "Pugnala un Devilsaur con la ⟦Devilsaur Barb=Daga del Gigantosauro⟧. Quando avrai completato questo compito, torna da Torwa Pathfinder nel ⟦Un'Goro Crater=Cratere di Un'Goro⟧.", "La tossina che mi hai aiutato a creare ha uno scopo speciale. I grandi gigantosauri del cratere rendono pericoloso cacciare e difficile sopravvivere per me. Anche se avessi la forza necessaria, uccidere un gigantosauro permetterebbe semplicemente a un altro di prendersi il suo territorio.\n\nPrendi questa daga avvelenata e piantala a fondo in un gigantosauro vivo. La tossina dovrebbe calmare la creatura, anche se non so quanto in fretta...", "Sei riuscit<o/a> a calmare la grande bestia?", "Grazie, {name}. Sei <coraggioso/coraggiosa> e <saggio/saggia>.\n\nDimmi, come ha reagito il gigantosauro alla tossina?", 0x48054159, 0x6be611fa, 0x8ef8e482, 0x1e668d2c, 0x521708f1, "....." },
  [9052] = { "⟦Bloodpetal Poison=Veleno di Petalorosso⟧", "Raccogli 8 Bloodcap e 8 Aculeo dei Gorishi, poi torna da Torwa Pathfinder nel ⟦Un'Goro Crater=Cratere di Un'Goro⟧.", "Vorrei chiederti di aiutarmi a creare una specie di tossina, per calmare una grande creatura che vive qui nel cratere. Non è letale, e solo gli occhi acuti di <un/una> {class} possono sperare di raccoglierne gli ingredienti.\n\nTroverai i funghi Bloodcap che crescono dentro i germogli di petalorosso in tutto il cratere. Gli aculei dei Gorishi vengono dalle vespe giganti volanti dentro e intorno all'Anfratto Brulicante, nella parte meridionale del cratere.", "Hai avuto successo?", "Finalmente gli ingredienti!\n\nCon il terreno di Un'Goro che ho raccolto, la tossina si prepara facilmente...", 0x1f178293, 0xf06ff794, 0xd296bd83, 0x7cadef78, 0x01ac2d01, "....." },
  [9053] = { "Un ingrediente migliore", "Recupera una ⟦Putrid Vine=Vite Putrida⟧ dal guardiano in fondo al Tempio di Atal'Hakkar e torna da Torwa Pathfinder.", "È come temevo: la tossina è semplicemente troppo debole per una creatura così potente.\n\nSe vogliamo creare una tossina abbastanza potente, devi scendere fino in fondo al Tempio di Atal'Hakkar, svelare i segreti dell'altare e recuperare una vite putrida dal guardiano che vi si trova. Il tempio è pericoloso, e faresti bene a portare degli amici.\n\nTorna da me quando avrai finito.", "Hai recuperato la vite?", "Finalmente la tossina può essere creata per intero. Non oso chiederti di infliggerla di nuovo alla creatura: ti ho già chiesto troppo.\n\nHai la mia gratitudine e il mio rispetto. Che i tuoi viaggi ti siano propizi, {name}.", 0xdb190fa9, 0x0ad68432, 0x3f4b427f, 0x25aa9248, 0xa8224e50, "....." },
  [9063] = { nil, "Parla con Torwa Pathfinder nel ⟦Un'Goro Crater=Cratere di Un'Goro⟧.", "Un cacciatore di nome Torwa Pathfinder ha chiesto l'aiuto di un druido. Ha detto che solo noi possediamo le capacità e il rispetto per la natura necessari per aiutarlo.\n\nC'è una strada che collega il ⟦Un'Goro Crater=Cratere di Un'Goro⟧ al deserto di Tanaris. Dove quella strada entra nel cratere, troverai Torwa lì vicino.", nil, "Hai viaggiato a lungo per incontrarmi, {class}, e appena in tempo.", 0x168fa4b2, 0x21114ed8, 0x5987fa9c, nil, 0x75c76210, "e..m." },
  [9065] = { "La missione \"Chow\" (123)aa", "Uccidi Kobold Vermin, 2 in tutto.", "$N1! Uccidi Kobold Vermin, 2 in tutto.", nil, nil, 0xdb0905c3, 0x314b469d, 0xb19a2ce2, nil, nil, "...mm" },
  [9085] = { nil, nil, nil, "Hai avuto fortuna, {name}?", nil, nil, nil, nil, 0x10763147, nil, "mmm.m" },
  [9124] = { "L'armatura Cryptstalker non si fa da sola...", "Il cacciatore Leopold, alla ⟦Light's Hope Chapel=Cappella della Luce⟧ nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧, vuole 30 ⟦Crypt Fiend Parts=Parti di Ragno delle Cripte⟧.", "Che ne diresti di guadagnarti una di queste monete luccicanti?\n\n<Leopold solleva un'insegna della Crociata.>\n\nHo un piccolo problema in cui potresti aiutarmi, {name}. Vedi, io realizzo armature Cryptstalker per chi è abbastanza matto da avventurarsi a Naxxramas. Loro mi forniscono i materiali principali per l'armatura, ma io resto sempre senza parti di ragno delle cripte. Portami un fascio di parti e ti pagherò con un'insegna, utilizzabile presso il furiere.", "Come va la caccia?", "Ah, questo andrà benissimo, {name}. Ricorda, accetto sempre altre parti. Per ogni fascio che mi porti, ti ricompenserò con un'insegna.", 0xa2b385ba, 0x878a3fbf, 0x61c659aa, 0xe02b27bb, 0xe90182ae, "....." },
  [9260] = { "Indagare sul Flagello a ⟦Stormwind=Roccavento⟧", "Raccogli 3 Pietra Necrotica Confusa dal Flagello fuori ⟦Stormwind=Roccavento⟧ e indaga sui cerchi runici luminosi vicino al loro accampamento.", "Il Flagello si è accampato proprio alle nostre porte: non possiamo restare con le mani in mano! Di certo ti farai avanti per difendere ⟦Stormwind=Roccavento⟧ da questi maledetti invasori?\n\nLà fuori ci sono strani cerchi runici, che brillano della stessa energia che circonda i non morti e la Necropoli lassù. Hanno un significato, ne sono certo, e voglio che tu scopra quale. Già che ci sei, sfoltisci le file di quegli abomini; portami la prova della loro morte insieme ai tuoi risultati e ti ricompenserò. Va'!", "Hai già indagato sull'invasione? Non c'è tempo da perdere!", "Mmm. Da ciò che mi hai detto, le voci dentro i cerchi... devono servire a comunicare in qualche modo. Rabbrividisco al pensiero di quali menti innaturali vengano contattate con una simile magia. In ogni caso, sembri esserne <uscito/uscita> <integro/integra> e <sano/sana> di mente. L'⟦Argent Dawn=Alba d'Argento⟧ apprezza il tuo servizio.", 0x00e4dbef, 0x9dc15400, 0x584b0283, 0x5ea2db66, 0x4f3229e9, "....." },
  [9261] = { "Indagine sul Flagello a ⟦Ironforge=Forgiardente⟧", "Raccogli tre Pietra Necrotica Confusa dal Flagello fuori da ⟦Ironforge=Forgiardente⟧ e indaga sui cerchi runici luminosi vicino al loro accampamento.", "Il Flagello si è accampato proprio alle nostre porte: non possiamo restare con le mani in mano! Di certo ti farai avanti per difendere ⟦Ironforge=Forgiardente⟧ da questi invasori maledetti?\n\nLà fuori ci sono strani cerchi runici, che brillano della stessa energia che circonda i non morti e la Necropoli lassù. Hanno un significato, ne sono certo, e voglio che tu scopra quale. Già che ci sei, sfoltisci le file di quegli abomini; portami la prova della loro morte insieme ai tuoi risultati e ti ricompenserò. Va'!", "Hai già indagato sull'invasione? Non c'è tempo da perdere!", "Mmm. Da ciò che mi hai detto, le voci dentro i cerchi... devono servire a comunicare in qualche modo. Rabbrividisco al pensiero di quali menti innaturali vengano contattate con una simile magia. In ogni caso, sembri esserne <uscito/uscita> <integro/integra> e <sano/sana> di mente. L'⟦Argent Dawn=Alba d'Argento⟧ apprezza il tuo servizio.", 0x71257d44, 0x40d576b1, 0x6d9b70a9, 0x5ea2db66, 0x4f3229e9, "....." },
  [9262] = { "Indagine sul Flagello a Darnassus", "Raccogli tre Pietra Necrotica Confusa dal Flagello fuori da Darnassus e indaga sui cerchi runici luminosi vicino al loro accampamento.", "Il Flagello si è accampato proprio alle nostre porte: non possiamo restare con le mani in mano! Di certo ti farai avanti per difendere Darnassus da questi invasori maledetti?\n\nLà fuori ci sono strani cerchi runici, che brillano della stessa energia che circonda i non morti e la Necropoli lassù. Hanno un significato, ne sono certo, e voglio che tu scopra quale. Già che ci sei, sfoltisci le file di quegli abomini; portami la prova della loro morte insieme ai tuoi risultati e ti ricompenserò. Va'!", "Hai già indagato sull'invasione? Non c'è tempo da perdere!", "Mmm. Da ciò che mi hai detto, le voci dentro i cerchi... devono servire a comunicare in qualche modo. Rabbrividisco al pensiero di quali menti innaturali vengano contattate con una simile magia. In ogni caso, sembri esserne <uscito/uscita> <integro/integra> e <sano/sana> di mente. L'⟦Argent Dawn=Alba d'Argento⟧ apprezza il tuo servizio.", 0xae0b4b57, 0x8c429383, 0x2683cc59, 0x5ea2db66, 0x4f3229e9, "....." },
  [9263] = { "Indagine sul Flagello a Orgrimmar", "Raccogli tre Pietra Necrotica Confusa dal Flagello fuori da Orgrimmar e indaga sui cerchi runici luminosi vicino al loro accampamento.", "Il Flagello si è accampato proprio alle nostre porte: non possiamo restare con le mani in mano! Di certo ti farai avanti per difendere Orgrimmar da questi invasori maledetti?\n\nLà fuori ci sono strani cerchi runici, che brillano della stessa energia che circonda i non morti e la Necropoli lassù. Hanno un significato, ne sono certo, e voglio che tu scopra quale. Già che ci sei, sfoltisci le file di quegli abomini; portami la prova della loro morte insieme ai tuoi risultati e ti ricompenserò. Va'!", "Hai già indagato sull'invasione? Non c'è tempo da perdere!", "Mmm. Da ciò che mi hai detto, le voci dentro i cerchi... devono servire a comunicare in qualche modo. Rabbrividisco al pensiero di quali menti innaturali vengano contattate con una simile magia. In ogni caso, sembri esserne <uscito/uscita> <integro/integra> e <sano/sana> di mente. L'⟦Argent Dawn=Alba d'Argento⟧ apprezza il tuo servizio.", 0xa887c042, 0xed596569, 0x4535136d, 0x5ea2db66, 0x4f3229e9, "....." },
  [9264] = { "Indagine sul Flagello a ⟦Thunder Bluff=Picco del Tuono⟧", "Raccogli tre Pietra Necrotica Confusa dal Flagello fuori da ⟦Thunder Bluff=Picco del Tuono⟧ e indaga sui cerchi runici luminosi vicino al loro accampamento.", "Il Flagello si è accampato proprio alle nostre porte: non possiamo restare con le mani in mano! Di certo ti farai avanti per difendere ⟦Thunder Bluff=Picco del Tuono⟧ da questi invasori maledetti?\n\nLà fuori ci sono strani cerchi runici, che brillano della stessa energia che circonda i non morti e la Necropoli lassù. Hanno un significato, ne sono certo, e voglio che tu scopra quale. Già che ci sei, sfoltisci le file di quegli abomini; portami la prova della loro morte insieme ai tuoi risultati e ti ricompenserò. Va'!", "Hai già indagato sull'invasione? Non c'è tempo da perdere!", "Mmm. Da ciò che mi hai detto, le voci dentro i cerchi... devono servire a comunicare in qualche modo. Rabbrividisco al pensiero di quali menti innaturali vengano contattate con una simile magia. In ogni caso, sembri esserne <uscito/uscita> <integro/integra> e <sano/sana> di mente. L'⟦Argent Dawn=Alba d'Argento⟧ apprezza il tuo servizio.", 0xa9531e97, 0x64454a5d, 0xb814786e, 0x5ea2db66, 0x4f3229e9, "....." },
  [9265] = { "Indagine sul Flagello di ⟦Undercity=Sepulcra⟧", "Raccogli tre Pietra Necrotica Confusa dal Flagello fuori da ⟦Undercity=Sepulcra⟧ e indaga sui cerchi runici luminosi vicino al loro accampamento.", "Il Flagello si è accampato proprio alle nostre porte; non possiamo restare con le mani in mano! Di certo ti farai avanti per difendere ⟦Undercity=Sepulcra⟧ da questi maledetti invasori, vero?\n\nLà fuori ci sono strani cerchi runici, che brillano della stessa energia che circonda i non morti e la Necropoli sopra di noi. Hanno un significato, ne sono certo, e voglio che tu scopra quale. Già che ci sei, sfoltisci le file di quegli abomini; portami la prova della loro morte insieme ai tuoi risultati e ti ricompenserò. Va'!", "Hai già indagato sull'invasione? Non c'è tempo da perdere!", "Mmm. Da ciò che mi hai detto, le voci dentro i cerchi... devono servire a comunicare in qualche modo. Rabbrividisco al pensiero di quali menti innaturali vengano contattate con una simile magia. In ogni caso, sembri esserne <uscito/uscita> <integro/integra> e <sano/sana> di mente. L'⟦Argent Dawn=Alba d'Argento⟧ apprezza il tuo servizio.", 0xe8ce843e, 0xae694c31, 0xcdb468ae, 0x5ea2db66, 0x4f3229e9, "....." },
  [9272] = { "Vestirsi per la parte", nil, nil, nil, "Yarrr... se ci tieni a goderti la compagnia di noi vecchi lupi di mare, faresti meglio a smettere di vestirti come un furfante! Ecco, mettiti addosso qualcosa di decente prima che ti faccia passare sotto la chiglia.\n\nQuesti ti staranno meglio di quanto siano mai stati a quel vecchio cane di Red-Eyed Ben. L'ho perso in mare, in una tempesta infernale.\n\nPortali con orgoglio, compare!", 0x09338667, nil, nil, nil, 0x35e4428b, ".mmm." },
  [9273] = { "Riscatta il ⟦iCoke Prize Voucher=Buono Premio iCola⟧", nil, nil, nil, nil, 0xfd599f6c, nil, nil, nil, nil, ".mmmm" },
  [9368] = { nil, nil, nil, "Hai avuto fortuna, {name}?", nil, nil, nil, nil, 0x10763147, nil, "mmm.m" },
  [9388] = { "Fiamme tremolanti a Kalimdor", "Visita i falò di ⟦Ashenvale=Valtetra⟧, delle ⟦Barrens=Savane⟧, di ⟦Darkshore=Rivafosca⟧ e delle ⟦Stonetalon Mountains=Vette di Petrartiglio⟧, poi parla con il custode della fiamma della festa.", "Oggi bruciano molte fiamme in tutto il mondo, {name}. I fuochi più difficili da curare sono quelli che ardono di verde: senza sorveglianza non restano accesi a lungo. Assicurati che i fuochi smeraldini ardano ancora su Kalimdor per il nostro custode della fiamma, eh?\n\nLi troverai vicino a ⟦Ratchet=Porto Paranco⟧ nelle ⟦Barrens=Savane⟧, vicino al ⟦Master's Glaive=Gladio del Maestro⟧ a ⟦Darkshore=Rivafosca⟧, nella foresta di ⟦Ashenvale=Valtetra⟧ presso il ponte vicino all'⟦Silverwing Outpost=Avamposto degli Alargentea⟧, e vicino alla strada per la ⟦Windshear Crag=Landa di Tagliavento⟧, lungo la strada principale delle ⟦Stonetalon Mountains=Vette di Petrartiglio⟧.", "I fuochi non possono spegnersi finché la festa non è finita!", "Ahhh, quindi ardono ancora. Ne sono lieto: non sarebbe giusto che quei fuochi si spegnessero prima del tempo. Hai fatto bene, {name}. Prendi questo, con la mia benedizione.", 0x4231b5a1, 0xebc13200, 0x9fb3b754, 0x7346e6f0, 0x87796b40, "....." },
  [9389] = { "Fiamme tremolanti nei Regni Orientali", "Visita i falò delle ⟦Hillsbrad Foothills=Alture di Colletorto⟧, della ⟦Silverpine Forest=Selva Pinargento⟧, delle ⟦Westfall=Marche Occidentali⟧ e delle ⟦Wetlands=Paludi Grigie⟧, poi parla con il custode della fiamma della festa.", "Per tradizione, i Fuochi di Mezza Estate illuminano il mondo con una miriade di fiamme. C'è chi sostiene che i fuochi verdi siano i più belli, perché sono i più difficili da mantenere e hanno una tinta così particolare.\n\nAssicurati che ardano ancora nei Regni Orientali per il nostro custode della fiamma. Si trovano vicino a Dun Modr nelle ⟦Wetlands=Paludi Grigie⟧, vicino a ⟦Pyrewood Village=Rovonero⟧ nella ⟦Silverpine Forest=Selva Pinargento⟧, sulle scogliere che sovrastano il faro nelle ⟦Westfall=Marche Occidentali⟧, e presso la torre in rovina nelle ⟦Hillsbrad Foothills=Alture di Colletorto⟧.", "Hai pensato al tuo compito?", "Allora sei tornat<o/a>, e ti sei occupat<o/a> delle fiamme smeraldine del continente. Che ne pensi, mm? Uno spettacolo raro e meraviglioso, senza dubbio. So però che le ricompense tangibili sono più apprezzate... quindi, ti prego, prendi questo per il disturbo.", 0x97c31d69, 0x8c77ebbe, 0x389c2696, 0x6640bff5, 0xe62c73ec, "....." },
})
